response:
{
  "id": "genetics-laws",
  "title": "遗传学定律",
  "subtitle": "从孟德尔到现代遗传学",
  "language": "zh-CN",
  "audience": "高中学生",
  "theme": "lab",
  "tutor": {
    "suggestions": [
      "为什么显性性状不一定更常见？",
      "如果父母都是双眼皮，孩子一定是双眼皮吗？",
      "如何区分显性纯合子和杂合子？",
      "自由组合定律的适用条件是什么？非等位基因一定自由组合吗？"
    ],
    "kb": [
      { "pattern": "显性|dominant", "answer": "在杂合子中能够表现出来的性状或等位基因。" },
      { "pattern": "隐性|recessive", "answer": "在杂合子中不表现，只有在纯合子中才表现的性状或等位基因。" },
      { "pattern": "等位基因|allele", "answer": "位于同源染色体相同位置上，控制同一性状不同表现形式的基因。" },
      { "pattern": "纯合子|homozygote", "answer": "同源染色体上相同位点的两个等位基因相同的个体，如 AA 或 aa。" },
      { "pattern": "杂合子|heterozygote", "answer": "同源染色体上相同位点的两个等位基因不同的个体，如 Aa。" },
      { "pattern": "测交|test cross", "answer": "将待测个体与隐性纯合子杂交，用以测定其基因型的方法。" }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "本课程从生活现象出发，逐步深入到遗传学定律的发现、验证、应用和扩展，帮助学生建立完整的遗传学知识体系。",
      "blocks": [
        { "id": "b_cover", "type": "hero", "intent": "封面：标题+一句副题" }
      ]
    },
    {
      "id": "intuition",
      "kind": "content",
      "eyebrow": "从生活出发",
      "headline": "为什么你像你的父母？",
      "lead": "耳垂、卷舌、单双眼皮——这些常见性状的传递隐藏着规律。",
      "notes": "通过展示人类常见性状的图片或描述，引导学生思考遗传现象。强调这些性状是离散的，不是混合的，为孟德尔的颗粒遗传做铺垫。可以让学生观察自己或同学的性状，统计班级比例，初步感受比例的存在。",
      "blocks": [
        { "id": "b1", "type": "list", "intent": "列举常见的人类单基因性状，如耳垂分离/附着、卷舌/非卷舌、单眼皮/双眼皮，并说明这些性状由单个基因控制，呈现显隐性关系。" },
        { "id": "b2", "type": "pullquote", "intent": "引用一句孟德尔或达尔文的话，或一个直观比喻：遗传因子就像颗粒，不是液体。" }
      ]
    },
    {
      "id": "mendel-design",
      "kind": "content",
      "eyebrow": "科学方法",
      "headline": "孟德尔为什么选择豌豆？",
      "lead": "自花传粉、闭花授粉、易于人工杂交、相对性状明显——实验材料的选择是成功的一半。",
      "notes": "介绍孟德尔的假说演绎法：提出问题（为什么性状会消失又出现？）→做出假设（遗传因子成对存在，分离）→演绎推理（如果假设正确，测交应得 1:1）→实验验证。强调孟德尔的定量分析思想，他统计了上万株豌豆，用数学方法处理数据，这是超越时代的关键。",
      "blocks": [
        { "id": "b3", "type": "flow", "intent": "展示假说演绎法的四个步骤：观察现象→提出假说→演绎推理→实验验证，用箭头连接。" },
        { "id": "b4", "type": "callout", "intent": "强调孟德尔的创新：定量统计、假说演绎、选择合适材料。" }
      ]
    },
    {
      "id": "segregation",
      "kind": "content",
      "eyebrow": "一对性状",
      "headline": "分离定律：3:1 的奥秘",
      "lead": "杂合子自交后代显隐比例 3:1，因为配子形成时等位基因彼此分离。",
      "notes": "用实物模拟：准备两个碗，分别代表父本和母本，碗中放两种颜色的球代表等位基因，随机抽取一个球模拟配子形成，然后组合成子代。重复多次，统计比例接近 3:1。强调分离发生在减数分裂形成配子时，而不是受精时。解释为什么显性性状不一定更常见：显性基因频率可能低。",
      "blocks": [
        { "id": "b5", "type": "flow", "intent": "用流程图展示：亲本（AA × aa）→ F1（Aa）→ 配子（A, a）→ 随机结合 → F2（AA, Aa, aA, aa）→ 表型比 3:1。" },
        { "id": "b6", "type": "formula", "intent": "用公式表示分离定律的实质：等位基因在减数分裂时分离，配子中只含每对等位基因中的一个。", "latex": "\\text{等位基因分离} \\Rightarrow \\text{配子类型比例 } 1:1" }
      ]
    },
    {
      "id": "independent-assortment",
      "kind": "content",
      "eyebrow": "两对性状",
      "headline": "自由组合定律：9:3:3:1 的棋盘",
      "lead": "两对等位基因位于非同源染色体上，配子形成时非等位基因自由组合。",
      "notes": "用棋盘法（Punnett square）展示 YyRr 自交后代 16 种组合，9 种基因型，4 种表型比例 9:3:3:1。强调自由组合的细胞学基础：减数分裂后期 I 非同源染色体自由组合。可以让学生动手画棋盘，计算比例。指出自由组合定律的适用条件：两对基因位于非同源染色体上。",
      "blocks": [
        { "id": "b7", "type": "table", "intent": "展示 Punnett 棋盘：父本配子（YR, Yr, yR, yr）和母本配子相同，交叉得到 16 格，每格填基因型，最后统计表型。" },
        { "id": "b8", "type": "callout", "intent": "提醒：自由组合定律的实质是减数分裂时非同源染色体的自由组合，不是配子的随机结合。" }
      ]
    },
    {
      "id": "cytology",
      "kind": "content",
      "eyebrow": "从因子到染色体",
      "headline": "减数分裂：遗传定律的细胞学证据",
      "lead": "等位基因随同源染色体分离而分离，非等位基因随非同源染色体自由组合而组合。",
      "notes": "展示减数分裂过程图，标注同源染色体分离（后期 I）和姐妹染色单体分离（后期 II）。将基因标注在染色体上，直观展示分离和自由组合。强调萨顿的假说：基因在染色体上，以及摩尔根的验证。可以对比分离定律和自由组合定律的染色体行为。",
      "blocks": [
        { "id": "b9", "type": "flow", "intent": "用流程图展示减数分裂关键步骤：间期复制 → 前期 I 联会 → 中期 I 同源染色体排列在赤道板 → 后期 I 同源染色体分离 → 后期 II 姐妹染色单体分离 → 配子。" },
        { "id": "b10", "type": "compare", "intent": "左右对比：分离定律（一对同源染色体分离）与自由组合定律（两对非同源染色体自由组合），用染色体图示。" }
      ]
    },
    {
      "id": "probability-testcross",
      "kind": "content",
      "eyebrow": "逻辑与验证",
      "headline": "如何用概率预测遗传结果？",
      "lead": "乘法原理和加法原理是遗传概率计算的基础，测交是验证假设的黄金标准。",
      "notes": "讲解乘法原理（独立事件同时发生的概率）和加法原理（互斥事件任一发生的概率）。用实例：AaBb 自交产生 A_bb 的概率 = 3/4 × 1/4 = 3/16。强调棋盘法本质是概率计算。介绍测交：与隐性纯合子杂交，子代表型比直接反映待测个体产生的配子类型及比例，是验证分离和自由组合的直接方法。",
      "blocks": [
        { "id": "b11", "type": "formula", "intent": "乘法原理：P(A and B) = P(A) × P(B)；加法原理：P(A or B) = P(A) + P(B)（互斥）。", "latex": "P(A \\cap B) = P(A) \\times P(B) \\quad \\text{（独立事件）}" },
        { "id": "b12", "type": "flow", "intent": "测交流程：待测个体 × 隐性纯合子 → 观察子代表型及比例 → 推断待测个体基因型。例如：AaBb × aabb → 若子代四种表型 1:1:1:1，则待测个体产生四种配子 1:1:1:1，证明自由组合。" }
      ]
    },
    {
      "id": "application-breeding",
      "kind": "content",
      "eyebrow": "学以致用",
      "headline": "如何培育纯合品种？",
      "lead": "连续自交和测交筛选是获得稳定遗传品种的经典方法。",
      "notes": "以小麦或豌豆为例，说明育种过程：从杂合子开始，连续自交，每代淘汰隐性性状，最终获得显性纯合子。计算自交 n 代后纯合子比例：1 - (1/2)^n。介绍回交育种：与亲本之一杂交，加速纯合。联系实际：杂交水稻利用杂种优势，但需年年制种。",
      "blocks": [
        { "id": "b13", "type": "flow", "intent": "展示育种流程：选择亲本杂交 → F1 自交 → F2 选择优良性状个体 → 连续自交 5-6 代 → 纯合品种。" },
        { "id": "b14", "type": "formula", "intent": "自交 n 代后杂合子比例 (1/2)^n，纯合子比例 1 - (1/2)^n。", "latex": "\\text{杂合子比例} = \\left(\\frac{1}{2}\\right)^n" }
      ]
    },
    {
      "id": "pedigree-analysis",
      "kind": "content",
      "eyebrow": "医学遗传",
      "headline": "系谱图：追踪遗传病的踪迹",
      "lead": "通过系谱图判断遗传方式，计算再发风险，是遗传咨询的核心技能。",
      "notes": "介绍系谱图常用符号（正方形、圆形、菱形，填充表示患病）。讲解判断遗传方式的口诀：无中生有为隐性，隐性遗传看女病，父子都病是伴性；有中生无为显性，显性遗传看男病，母女都病是伴性。用实例：一个常染色体隐性遗传病系谱（如白化病），计算表兄妹结婚后子女患病风险。强调近亲结婚增加隐性遗传病风险的原因：共同祖先携带相同隐性致病基因的概率高。",
      "blocks": [
        { "id": "b15", "type": "flow", "intent": "系谱分析步骤：1. 判断显隐性；2. 判断常染色体/伴性；3. 确定基因型；4. 计算概率。" },
        { "id": "b16", "type": "callout", "intent": "举例：一对表兄妹，其共同祖母是白化病携带者，计算他们子女患病风险。强调近亲结婚的危害。" }
      ]
    },
    {
      "id": "extensions-1",
      "kind": "content",
      "eyebrow": "超越孟德尔",
      "headline": "当显性不是完全的时候",
      "lead": "不完全显性、共显性、复等位基因——孟德尔比例的修正与丰富。",
      "notes": "用金鱼草花色（红花×白花→粉红花）说明不完全显性，F2 表型比 1:2:1 而非 3:1。用 ABO 血型说明共显性（IA 和 IB 共显）和复等位基因（IA, IB, i 三个等位基因）。强调这些现象并不否定分离定律，只是显性关系不同。ABO 血型遗传仍遵循分离定律，只是等位基因多于两个。",
      "blocks": [
        { "id": "b17", "type": "compare", "intent": "左右对比：完全显性（3:1）、不完全显性（1:2:1）、共显性（1:2:1，但表型不同），用花色或血型示例。" },
        { "id": "b18", "type": "table", "intent": "ABO 血型基因型与表型对应表：IAIA, IAi → A 型；IBIB, IBi → B 型；IAIB → AB 型；ii → O 型。" }
      ]
    },
    {
      "id": "extensions-2",
      "kind": "content",
      "eyebrow": "更复杂的遗传",
      "headline": "基因在染色体上线性排列",
      "lead": "摩尔根的果蝇实验证明基因连锁与互换，揭示基因的染色体定位。",
      "notes": "介绍摩尔根的白眼果蝇实验，发现白眼基因位于 X 染色体上，伴性遗传。进一步发现同一染色体上的基因倾向于连锁遗传，但可通过互换重组。解释重组率与基因距离的关系：重组率越高，基因距离越远。简述多基因遗传：身高、肤色等由多对基因控制，呈连续分布，环境因素也有影响。强调孟德尔定律是基础，复杂性状仍由单个基因的分离和自由组合（或连锁）决定。",
      "blocks": [
        { "id": "b19", "type": "flow", "intent": "连锁与互换示意图：两对基因位于同一染色体，减数分裂时可能发生交叉互换，产生重组型配子。" },
        { "id": "b20", "type": "callout", "intent": "多基因遗传举例：假设身高由 3 对基因控制，每对基因有高矮两个等位基因，高基因数量越多身高越高，呈正态分布。" }
      ]
    },
    {
      "id": "quiz",
      "kind": "quiz",
      "headline": "随堂检验：你掌握遗传定律了吗？",
      "notes": "通过几个典型题目检验学生对分离定律、自由组合定律、概率计算、系谱分析的理解。题目设计应覆盖不同难度，包括基础概念、计算、应用和推理。可以设计一个综合题：给出一个系谱和基因型信息，要求计算某个体患病概率。",
      "blocks": [
        { "id": "b21", "type": "quiz", "intent": "考察点：1. 分离定律的实质；2. 自由组合定律的适用条件；3. 概率计算（乘法原理）；4. 系谱分析判断遗传方式；5. 连锁与互换的基本概念。" }
      ]
    }
  ]
}
